import type { Metadata } from "next";
import type { Lang } from "@/dictionaries";

export const OG_ALT: Record<Lang, string> = {
  en: "Kidsit AI, your AI parenting copilot, with the app's home screen",
  he: "Kidsit AI – עוזר הורות, מסך הבית של האפליקציה",
};

// The share card generated by app/[lang]/og-image.png/route.tsx.
export const card = (lang: Lang) => ({
  url: `/${lang}/og-image.png`,
  width: 1200,
  height: 630,
  type: "image/png",
  alt: OG_ALT[lang],
});

type OgType = "website" | "article";

// A page-level openGraph object replaces the layout's, so every page (home via the layout, and privacy, terms,
// support, accessibility, blog) spreads this to get the share image, site name, type and locale.
export function ogFor(
  lang: Lang,
  title: string,
  description: string,
  path: string,
  type: OgType = "website",
): Pick<Metadata, "openGraph" | "twitter"> {
  return {
    openGraph: {
      type,
      siteName: "Kidsit AI",
      locale: lang === "he" ? "he_IL" : "en_US",
      url: `/${lang}${path}`,
      title,
      description,
      images: [card(lang)],
    },
    twitter: { card: "summary_large_image", title, description, images: [card(lang)] },
  };
}
